(function($){$(document).ready(function(){$(document).on('input','.sheyda-wallet-price-input',function(){$(this).val(sheydaWallet.formatPrice($(this).val()))})
$(document).on('input','.sheyda-wallet-numeric-input',function(){const $input=$(this);let value=sheydaWallet.convertChars($input.val()).trim().replace(/[^0-9]/g,'');$input.val(value)});$(document).on('input',".sheyda-wallet-card-number-input",function(){const $input=$(this);let value=sheydaWallet.convertChars($input.val()).trim().replace(/\D/g,'').slice(0,16);value=value.replace(/^(\d{4})(\d{0,4})(\d{0,4})(\d{0,4})$/,(_,a,b,c,d)=>{return[a,b,c,d].filter(Boolean).join(' ')});$input.val(value)});$(document).on('input',".sheyda-wallet-shaba-number-input",function(){const $input=$(this);let value=sheydaWallet.convertChars($input.val()).trim().replace(/\D/g,'').slice(0,24);value=value.replace(/^(\d{2})(\d{0,4})(\d{0,4})(\d{0,4})(\d{0,4})(\d{0,4})(\d{0,2})$/,(_,a,b,c,d,e,f,g)=>{return[a,b,c,d,e,f,g].filter(Boolean).join(' ')});$input.val(`IR${value}`)});sheydaWallet.initSelect2()})})(jQuery)